<script>(()=>{const nav=document.querySelector('[data-a853-nav]'),menu=document.querySelector('[data-a853-menu]');menu?.addEventListener('click',()=>{nav?.classList.toggle('is-open');menu.setAttribute('aria-label',nav?.classList.contains('is-open')?'Đóng menu':'Mở menu')});document.querySelectorAll('[data-a853-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-a853-slide]')];if(slides.length<2)return;let i=0;const show=n=>{slides[i].classList.remove('is-active');i=(n+slides.length)%slides.length;slides[i].classList.add('is-active')};slider.querySelector('[data-a853-prev]')?.addEventListener('click',()=>show(i-1));slider.querySelector('[data-a853-next]')?.addEventListener('click',()=>show(i+1));setInterval(()=>show(i+1),Math.max(4500,Number(slider.dataset.autoplay||6500)))})})();</script>
